const prev = $('1. Flow 2 Webhook Trigger').first().json;
const payload = prev.body ? prev.body : prev;

const subject = (payload.subject || "").toLowerCase();
const body = (payload.body || "").toLowerCase();
const text = subject + " " + body;

let category = "General";
let priority = "P3 - Medium";
let sentiment = "Trung tinh";
let urgencyReason = "Thư tiếp nhận thông thường";

if (text.includes("sập") || text.includes("504") || text.includes("500") || text.includes("không truy cập") || text.includes("khẩn cấp") || text.includes("down") || text.includes("outage")) {
  category = "Technical";
  priority = "P1 - Critical";
  sentiment = "Khan cap";
  urgencyReason = "Hệ thống ghi nhận sự cố gián đoạn dịch vụ diện rộng cần xử lý khẩn";
} else if (text.includes("lỗi") || text.includes("api") || text.includes("bug") || text.includes("database") || text.includes("không đăng nhập") || text.includes("mật khẩu")) {
  category = "Technical";
  priority = "P2 - High";
  sentiment = "Tieu cuc";
  urgencyReason = "Yêu cầu hỗ trợ khắc phục sự cố kỹ thuật chức năng";
} else if (text.includes("báo giá") || text.includes("mua hàng") || text.includes("hợp đồng") || text.includes("bản quyền") || text.includes("tư vấn")) {
  category = "Sales";
  priority = "P2 - High";
  sentiment = "Tich cuc";
  urgencyReason = "Yêu cầu tư vấn cơ hội kinh doanh và báo giá giải pháp";
} else if (text.includes("hóa đơn") || text.includes("vat") || text.includes("công nợ") || text.includes("thanh toán") || text.includes("chứng từ")) {
  category = "Finance";
  priority = "P3 - Medium";
  sentiment = "Trung tinh";
  urgencyReason = "Yêu cầu đối soát chứng từ và phát hành hóa đơn kế toán";
}

return [{
  json: {
    ...payload,
    sender_email: payload.sender_email || payload.from || "guest@enterprise.com",
    sender_name: payload.sender_name || payload.name || "Khách Hàng",
    subject: payload.subject || "Yêu cầu tiếp nhận",
    body: payload.body || payload.text || "",
    category: category,
    priority: priority,
    sentiment: sentiment,
    urgency_reason: urgencyReason
  }
}];

const current = $input.first().json;

let slaHours = 8;
if (current.priority.includes('P1')) slaHours = 2;
else if (current.priority.includes('P2')) slaHours = 4;
else if (current.priority.includes('P3')) slaHours = 8;
else if (current.priority.includes('P4')) slaHours = 24;

const slaDeadline = new Date(Date.now() + slaHours * 3600 * 1000).toISOString();

return [{
  json: {
    ...current,
    sla_deadline: slaDeadline,
    sla_hours: slaHours
  }
}];

